-- 36_reimport_oktober_2026.sql
-- Spielt den SFP-Bericht Oktober 2026 (Stand 16.11.) in die Tabelle performance ein – gleiche Regeln wie der Cronjob:
--   * je Mitarbeiter und Tag wird die Zeile überschrieben (Upsert auf employee_id + date)
--   * Tage mit 0 € Gesamt-Margenerhöhung werden nicht importiert; steht so ein Tag noch in der Datenbank, wird er gelöscht
--   * HO/SOM-Kennungen werden ignoriert
-- Vorher wird der Oktober gesichert: backup_20261116_performance_okt. NUR in Live ausführen. Mehrfach unbedenklich.

begin;
create table if not exists public.backup_20261116_performance_okt as select * from public.performance where date between '2026-10-01' and '2026-10-31';
alter table public.backup_20261116_performance_okt enable row level security;
revoke all on public.backup_20261116_performance_okt from anon, authenticated;

drop table if exists pg_temp.imp_okt;
create temp table imp_okt (name text, date date, wochentag text, oem_aktivitaeten numeric, oem_nicht_erreicht numeric, oem_nicht_erfolgreich numeric, oem_nicht_moeglich numeric, oem_gesamt numeric, oem_tw numeric, oem_yes numeric, oem_sy numeric, oem_my numeric, ups_yes numeric, wka_gesamt_yes numeric, gesamt_optimierungen numeric, oem_margenerhoehung numeric, ups_margenerhoehung numeric, wka_margenerhoehung numeric, gesamt_margenerhoehung numeric, oem_storniert numeric, oem_kein numeric, oem_umsatz numeric, oem_kompa_umsatzerhoehung numeric, oem_rabatte_summe numeric, oem_rabatte_anzahl numeric, oem_shop_rabatte_summe numeric, oem_shop_rabatte_anzahl numeric, oem_widerrufen numeric, ups_aktivitaeten numeric, ups_nicht_erreicht numeric, ups_nicht_erfolgreich numeric, ups_nicht_moeglich numeric, ups_storniert numeric, ups_gesamt numeric, ups_umsatz numeric, ups_kompa_umsatzerhoehung numeric, ups_rabatte_summe numeric, ups_rabatte_anzahl numeric, ups_shop_rabatte_summe numeric, ups_shop_rabatte_anzahl numeric, ups_widerrufen numeric, wka_oem_aktivitaeten numeric, wka_oem_nicht_erreicht numeric, wka_oem_nicht_erfolgreich numeric, wka_oem_beendet numeric, wka_oem_tw numeric, wka_oem_yes numeric, wka_oem_super_yes numeric, wka_oem_mega_yes numeric, wka_oem_gesamt numeric, wka_oem_margenerhoehung numeric, wka_oem_umsatz numeric, wka_oem_kompa_umsatzerhoehung numeric, wka_oem_rabatte_summe numeric, wka_oem_rabatte_anzahl numeric, wka_oem_widerrufen numeric, wka_ups_aktivitaeten numeric, wka_ups_nicht_erreicht numeric, wka_ups_nicht_erfolgreich numeric, wka_ups_beendet numeric, wka_ups_yes numeric, wka_ups_gesamt numeric, wka_ups_margenerhoehung numeric, wka_ups_umsatz numeric, wka_ups_kompa_umsatzerhoehung numeric, wka_ups_rabatte_summe numeric, wka_ups_rabatte_anzahl numeric, wka_ups_widerrufen numeric, gesamt_aktivitaeten numeric, gesamt_nicht_erreicht numeric, gesamt_nicht_erfolgreich numeric, gesamt_nicht_moeglich numeric, gesamt_storniert numeric, gesamt_widerrufen numeric);

drop table if exists pg_temp.imp_map;
create temp table imp_map as select distinct i.name, (select e.id from public.employees e where lower(regexp_replace(trim(e.name),'\s+',' ','g')) = lower(regexp_replace(trim(i.name),'\s+',' ','g')) limit 1) as employee_id from imp_okt i;

select m.employee_id, i.date, i.wochentag, i.oem_aktivitaeten, i.oem_nicht_erreicht, i.oem_nicht_erfolgreich, i.oem_nicht_moeglich, i.oem_gesamt, i.oem_tw, i.oem_yes, i.oem_sy, i.oem_my, i.ups_yes, i.wka_gesamt_yes, i.gesamt_optimierungen, i.oem_margenerhoehung, i.ups_margenerhoehung, i.wka_margenerhoehung, i.gesamt_margenerhoehung, i.oem_storniert, i.oem_kein, i.oem_umsatz, i.oem_kompa_umsatzerhoehung, i.oem_rabatte_summe, i.oem_rabatte_anzahl, i.oem_shop_rabatte_summe, i.oem_shop_rabatte_anzahl, i.oem_widerrufen, i.ups_aktivitaeten, i.ups_nicht_erreicht, i.ups_nicht_erfolgreich, i.ups_nicht_moeglich, i.ups_storniert, i.ups_gesamt, i.ups_umsatz, i.ups_kompa_umsatzerhoehung, i.ups_rabatte_summe, i.ups_rabatte_anzahl, i.ups_shop_rabatte_summe, i.ups_shop_rabatte_anzahl, i.ups_widerrufen, i.wka_oem_aktivitaeten, i.wka_oem_nicht_erreicht, i.wka_oem_nicht_erfolgreich, i.wka_oem_beendet, i.wka_oem_tw, i.wka_oem_yes, i.wka_oem_super_yes, i.wka_oem_mega_yes, i.wka_oem_gesamt, i.wka_oem_margenerhoehung, i.wka_oem_umsatz, i.wka_oem_kompa_umsatzerhoehung, i.wka_oem_rabatte_summe, i.wka_oem_rabatte_anzahl, i.wka_oem_widerrufen, i.wka_ups_aktivitaeten, i.wka_ups_nicht_erreicht, i.wka_ups_nicht_erfolgreich, i.wka_ups_beendet, i.wka_ups_yes, i.wka_ups_gesamt, i.wka_ups_margenerhoehung, i.wka_ups_umsatz, i.wka_ups_kompa_umsatzerhoehung, i.wka_ups_rabatte_summe, i.wka_ups_rabatte_anzahl, i.wka_ups_widerrufen, i.gesamt_aktivitaeten, i.gesamt_nicht_erreicht, i.gesamt_nicht_erfolgreich, i.gesamt_nicht_moeglich, i.gesamt_storniert, i.gesamt_widerrufen
from imp_okt i join imp_map m on m.name = i.name
where m.employee_id is not null and coalesce(i.gesamt_margenerhoehung,0) <> 0
on conflict (employee_id, date) do update set wochentag = excluded.wochentag, oem_aktivitaeten = excluded.oem_aktivitaeten, oem_nicht_erreicht = excluded.oem_nicht_erreicht, oem_nicht_erfolgreich = excluded.oem_nicht_erfolgreich, oem_nicht_moeglich = excluded.oem_nicht_moeglich, oem_gesamt = excluded.oem_gesamt, oem_tw = excluded.oem_tw, oem_yes = excluded.oem_yes, oem_sy = excluded.oem_sy, oem_my = excluded.oem_my, ups_yes = excluded.ups_yes, wka_gesamt_yes = excluded.wka_gesamt_yes, gesamt_optimierungen = excluded.gesamt_optimierungen, oem_margenerhoehung = excluded.oem_margenerhoehung, ups_margenerhoehung = excluded.ups_margenerhoehung, wka_margenerhoehung = excluded.wka_margenerhoehung, gesamt_margenerhoehung = excluded.gesamt_margenerhoehung, oem_storniert = excluded.oem_storniert, oem_kein = excluded.oem_kein, oem_umsatz = excluded.oem_umsatz, oem_kompa_umsatzerhoehung = excluded.oem_kompa_umsatzerhoehung, oem_rabatte_summe = excluded.oem_rabatte_summe, oem_rabatte_anzahl = excluded.oem_rabatte_anzahl, oem_shop_rabatte_summe = excluded.oem_shop_rabatte_summe, oem_shop_rabatte_anzahl = excluded.oem_shop_rabatte_anzahl, oem_widerrufen = excluded.oem_widerrufen, ups_aktivitaeten = excluded.ups_aktivitaeten, ups_nicht_erreicht = excluded.ups_nicht_erreicht, ups_nicht_erfolgreich = excluded.ups_nicht_erfolgreich, ups_nicht_moeglich = excluded.ups_nicht_moeglich, ups_storniert = excluded.ups_storniert, ups_gesamt = excluded.ups_gesamt, ups_umsatz = excluded.ups_umsatz, ups_kompa_umsatzerhoehung = excluded.ups_kompa_umsatzerhoehung, ups_rabatte_summe = excluded.ups_rabatte_summe, ups_rabatte_anzahl = excluded.ups_rabatte_anzahl, ups_shop_rabatte_summe = excluded.ups_shop_rabatte_summe, ups_shop_rabatte_anzahl = excluded.ups_shop_rabatte_anzahl, ups_widerrufen = excluded.ups_widerrufen, wka_oem_aktivitaeten = excluded.wka_oem_aktivitaeten, wka_oem_nicht_erreicht = excluded.wka_oem_nicht_erreicht, wka_oem_nicht_erfolgreich = excluded.wka_oem_nicht_erfolgreich, wka_oem_beendet = excluded.wka_oem_beendet, wka_oem_tw = excluded.wka_oem_tw, wka_oem_yes = excluded.wka_oem_yes, wka_oem_super_yes = excluded.wka_oem_super_yes, wka_oem_mega_yes = excluded.wka_oem_mega_yes, wka_oem_gesamt = excluded.wka_oem_gesamt, wka_oem_margenerhoehung = excluded.wka_oem_margenerhoehung, wka_oem_umsatz = excluded.wka_oem_umsatz, wka_oem_kompa_umsatzerhoehung = excluded.wka_oem_kompa_umsatzerhoehung, wka_oem_rabatte_summe = excluded.wka_oem_rabatte_summe, wka_oem_rabatte_anzahl = excluded.wka_oem_rabatte_anzahl, wka_oem_widerrufen = excluded.wka_oem_widerrufen, wka_ups_aktivitaeten = excluded.wka_ups_aktivitaeten, wka_ups_nicht_erreicht = excluded.wka_ups_nicht_erreicht, wka_ups_nicht_erfolgreich = excluded.wka_ups_nicht_erfolgreich, wka_ups_beendet = excluded.wka_ups_beendet, wka_ups_yes = excluded.wka_ups_yes, wka_ups_gesamt = excluded.wka_ups_gesamt, wka_ups_margenerhoehung = excluded.wka_ups_margenerhoehung, wka_ups_umsatz = excluded.wka_ups_umsatz, wka_ups_kompa_umsatzerhoehung = excluded.wka_ups_kompa_umsatzerhoehung, wka_ups_rabatte_summe = excluded.wka_ups_rabatte_summe, wka_ups_rabatte_anzahl = excluded.wka_ups_rabatte_anzahl, wka_ups_widerrufen = excluded.wka_ups_widerrufen, gesamt_aktivitaeten = excluded.gesamt_aktivitaeten, gesamt_nicht_erreicht = excluded.gesamt_nicht_erreicht, gesamt_nicht_erfolgreich = excluded.gesamt_nicht_erfolgreich, gesamt_nicht_moeglich = excluded.gesamt_nicht_moeglich, gesamt_storniert = excluded.gesamt_storniert, gesamt_widerrufen = excluded.gesamt_widerrufen;

delete from public.performance p using imp_okt i join imp_map m on m.name = i.name
where m.employee_id is not null and p.employee_id = m.employee_id and p.date = i.date and coalesce(i.gesamt_margenerhoehung,0) = 0;

commit;

-- Kontrolle: Oktober je Mitarbeiter (sollte jetzt der SFP entsprechen); nicht zugeordnete Namen stehen mit leerem Mitarbeiter da
select coalesce(e.name, m.name || ' (NICHT zugeordnet)') as mitarbeiter, count(p.date) as tage_mit_daten,
       sum(p.oem_tw+p.oem_yes+p.oem_sy+p.oem_my) as opt_oem, sum(p.oem_nicht_erfolgreich) as oem_nicht_erfolgreich,
       sum(p.gesamt_optimierungen) as opt_ges, round(sum(p.gesamt_margenerhoehung)::numeric,2) as marge
from imp_map m left join public.employees e on e.id = m.employee_id
left join public.performance p on p.employee_id = m.employee_id and p.date between '2026-10-01' and '2026-10-31'
group by 1 order by 1;
